String inputJson = (String)globalMap.get("message");

// Check if the input is a valid JSON object or array
try {
    // Attempt to parse the input as a JSONObject
    JSONObject jsonObject = new JSONObject(inputJson);

    // If we can parse it as a JSONObject, then it's a dictionary.
    // Transform the dictionary to an array.
    JSONArray resultArray = new JSONArray();
    JSONObject shipmentOrderLine = jsonObject.optJSONObject("shipmentOrderLine");

    if (shipmentOrderLine != null) {
        // Add the shipmentOrderLine object to the array
        resultArray.put(shipmentOrderLine);
    }

    // Set the transformed result to the output row (use your actual output variable name here)
    String transformedMessage = resultArray.toString();
    globalMap.put("shipmentOrderLine", transformedMessage);

} catch (Exception e) {
    // If the input is not a valid JSONObject, check if it's a JSONArray.
    try {
        // Attempt to parse the input as a JSONArray
        JSONArray jsonArray = new JSONArray(inputJson);

        // If it's a valid JSONArray, do nothing and just output the input.
        String transformedMessage = jsonArray.toString();
        globalMap.put("shipmentOrderLine", transformedMessage);

    } catch (Exception ex) {
        // Handle parsing error, if needed
        System.err.println("Invalid input format: " + inputJson);
    }
}

import org.json.JSONObject;
